// Writes the colour tokens from src/theme/tokens.ts as native colours for both keyboards.
import { colors } from '../../src/theme/tokens.ts';

export const SWIFT_THEME_OUT = 'targets/keyboard/UI/Theme.generated.swift';
export const ANDROID_COLORS_OUT = 'modules/replywise-ime/android/src/main/res/values/colors.xml';
export const ANDROID_COLORS_NIGHT_OUT =
  'modules/replywise-ime/android/src/main/res/values-night/colors.xml';

const HEADER =
  'GENERATED by scripts/export-tokens.ts from src/theme/tokens.ts. Do not edit; run `npm run gen:tokens`.';

type Name = keyof (typeof colors)['light'];
const names = Object.keys(colors.light) as Name[];

const hex = (value: string) => `0x${value.replace('#', '').toUpperCase()}`;

/** "surfaceRaised" → "rw_surface_raised" */
export function androidColorName(name: string): string {
  return `rw_${name.replace(/([a-z0-9])([A-Z])/g, '$1_$2').toLowerCase()}`;
}

/**
 * iOS Increase Contrast (traits.accessibilityContrast == .high): these tokens switch to a stronger
 * existing token. Derived from tokens.ts, no new values. Key outlines use borderStrong directly.
 */
export const HIGH_CONTRAST: Partial<Record<Name, Name>> = {
  textSecondary: 'text',
};

export function generateSwiftTheme(): string {
  const lines = names.map((n) => {
    const strong = HIGH_CONTRAST[n] ?? n;
    return (
      `    static let ${n} = dynamic(light: ${hex(colors.light[n])}, dark: ${hex(colors.dark[n])}, ` +
      `lightHighContrast: ${hex(colors.light[strong])}, darkHighContrast: ${hex(colors.dark[strong])})`
    );
  });
  return `// ${HEADER}

import SwiftUI
import UIKit

/// Keyboard colours, identical to the app's tokens. Each one follows light/dark mode and
/// Increase Contrast (Settings → Accessibility → Display & Text Size).
enum KeyboardTheme {
${lines.join('\n')}

    private static func dynamic(light: UInt32, dark: UInt32, lightHighContrast: UInt32, darkHighContrast: UInt32) -> Color {
        Color(UIColor { traits in
            let high = traits.accessibilityContrast == .high
            if traits.userInterfaceStyle == .dark {
                return rgb(high ? darkHighContrast : dark)
            }
            return rgb(high ? lightHighContrast : light)
        })
    }

    private static func rgb(_ value: UInt32) -> UIColor {
        UIColor(
            red: CGFloat((value >> 16) & 0xFF) / 255,
            green: CGFloat((value >> 8) & 0xFF) / 255,
            blue: CGFloat(value & 0xFF) / 255,
            alpha: 1
        )
    }
}
`;
}

export function generateAndroidColors(scheme: 'light' | 'dark'): string {
  const lines = names.map(
    (n) => `    <color name="${androidColorName(n)}">${colors[scheme][n].toUpperCase()}</color>`,
  );
  return `<?xml version="1.0" encoding="utf-8"?>
<!-- ${HEADER} -->
<resources>
${lines.join('\n')}
</resources>
`;
}

export function generateThemeFiles(): Map<string, string> {
  return new Map([
    [SWIFT_THEME_OUT, generateSwiftTheme()],
    [ANDROID_COLORS_OUT, generateAndroidColors('light')],
    [ANDROID_COLORS_NIGHT_OUT, generateAndroidColors('dark')],
  ]);
}
